import type { App } from 'vue'
import VueTippy from 'vue-tippy'
import 'tippy.js/dist/tippy.css'
import 'tippy.js/animations/shift-away.css'
import './style/themes.css'

export const pfTooltipPlugin = (app: App) => {
  app.use(VueTippy, {
    directive: 'pf-tooltip',
    component: 'pf-tooltip',
    componentSingleton: 'pf-tooltip-singleton',
    defaultProps: {
      placement: 'top',
      theme: 'pf-tooltip',
      animation: 'shift-away',
      touch: ['hold', 500],
    },
  })
}

/**
 * PfTooltip 主题。
 *
 * 颜色语义：design 的 `popover` 是「脱离文档流的浮层表面」，与 modal、
 * dropdown 统一；此前这里误用 `foreground` 当背景（深浅颠倒），亮色下
 * 会变成一块深色方块。
 *
 * ⚠️ 箭头只能设置 `color`，绝不能给 `.tippy-arrow::before` 加 border。
 * tippy 的三角形是拿 8px 的 `border` 画出来的：`border-color: transparent`
 * 打底，再单独给朝外那一侧上色（`border-top-color: initial` 即 currentColor）。
 * 一旦额外声明 `border: 1px solid`，四个方向全被改成 1px 实线，
 * 三角形几何直接塌掉——表现就是「箭头不见了」，只剩一个描边小方框。
 */
.tippy-box[data-theme~='pf-tooltip'] {
  background: var(--popover);
  color: var(--popover-foreground);
  border: 1px solid var(--border);
  box-shadow: 0 8px 24px color-mix(in srgb, var(--foreground) 12%, transparent);
}

.tippy-box[data-theme~='pf-tooltip'] > .tippy-content {
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  line-height: 1rem;
}

/* 三角形的颜色完全由 `color` 驱动，形状交给 tippy 官方样式。 */
.tippy-box[data-theme~='pf-tooltip'] > .tippy-arrow {
  color: var(--popover);
}
